});

test('invoiceTotals with undefined discountPercent defaults to 0', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 0);
  assert.equal(totals.subtotal, 85000);
});

test('invoiceTotals calculation example from docs', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 85000
  // First discount (10%): 8500
  // Bulk discount (2.5% of 76500): 1912
  // Total discount: 10412
  // After discount: 74588
  // VAT: 15663
  // Total: 90251
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 10412);
  assert.equal(totals.vat, 15663);
  assert.equal(totals.total, 90251);
});

test('invoiceTotals with complex multi-line scenario', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 5, vatRate: 21 },
      { qty: 100, unitPrice: 37, discountPercent: 0, vatRate: 9 },
      { qty: 5, unitPrice: 100, discountPercent: 10, vatRate: 0 },
    ],
    voucher: { amount: 10000 },
  };
  const totals = invoiceTotals(invoice);

  // Line 1: 85000 - 4250 = 80750, VAT: 16958 (rounded)
  // Line 2: 3700 - 0 = 3700, VAT: 333
  // Line 3: 500 - 50 = 450, VAT: 0
  // Subtotal: 89200, Discount: 4300, VAT: 17291, Voucher: 10000
  // Total: 89200 - 4300 + 17291 - 10000 = 92191

  assert.equal(totals.subtotal, 89200);
  assert.ok(totals.discount > 0);
  assert.ok(totals.vat > 0);
  assert.equal(totals.voucher, 10000);
  assert.ok(totals.total > 0);
});

test('invoiceTotals with bulk discount at 10 units', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 1000
  // First discount: 0
  // Bulk discount (2.5% of 1000): 25
  // After discount: 975
  // VAT: 975 * 21% = 204.75 → 205 (banker's rounding)
  // Total: 1000 - 25 + 205 = 1180
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 25);
  assert.equal(totals.vat, 205);
  assert.equal(totals.total, 1180);
});

test('invoiceTotals no bulk discount at 9 units', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 900
  // No bulk discount (qty < 10)
  // VAT: 900 * 21% = 189
  // Total: 900 + 189 = 1089
  assert.equal(totals.subtotal, 900);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 189);
  assert.equal(totals.total, 1089);
});

test('invoiceTotals bulk discount applied after line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 1000
  // First discount (10%): 100
  // After first discount: 900
  // Bulk discount (2.5% of 900): 22.5 → 22 (banker's rounding)
  // Total discount: 100 + 22 = 122
  // After discount: 878
  // VAT: 878 * 21% = 184.38 → 184 (banker's rounding)
  // Total: 1000 - 122 + 184 = 1062
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 122);
});

test('invoiceTotals with bulk discount on large quantity', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 50, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 5000
  // First discount: 0
  // Bulk discount (2.5% of 5000): 125
  // After discount: 4875
  // VAT: 4875 * 9% = 438.75 → 439 (banker's rounding)
  // Total: 5000 - 125 + 439 = 5314
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 125);
  assert.equal(totals.vat, 439);
  assert.equal(totals.total, 5314);
});

test('invoiceTotals multiple lines with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 100, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 1000, bulk discount 25, after discount 975, VAT 205
  // Line 2: 500, no bulk discount, VAT 105
  // Subtotal: 1500, Discount: 25, VAT: 310, Total: 1785
  assert.equal(totals.subtotal, 1500);
  assert.equal(totals.discount, 25);
});

test('invoiceTotals bulk discount with existing discount reduces VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 10000
  // First discount (5%): 500
  // After first discount: 9500
  // Bulk discount (2.5% of 9500): 237.5 → 238 (banker's rounding)
  // Total discount: 500 + 238 = 738
  // After discount: 9262
  // VAT: 9262 * 21% = 1945.02 → 1945
  // Total: 10000 - 738 + 1945 = 11207
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 738);
});

test('invoiceTotals bulk discount exact boundary', () => {
  const invoice = {
    lines: [
      { qty: 11, unitPrice: 100, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 1100
  // Bulk discount (2.5% of 1100): 27.5 → 28 (banker's rounding)
  // After discount: 1072
  // VAT: 0
  // Total: 1100 - 28 = 1072
  assert.equal(totals.subtotal, 1100);
  assert.equal(totals.discount, 28);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 1072);
});

test('invoiceTotals no bulk discount at exactly 9 units', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 9000
  // No bulk discount (qty = 9, need >= 10)
  // VAT: 9000 * 21% = 1890
  // Total: 10890
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1890);
  assert.equal(totals.total, 10890);
});

test('invoiceTotals bulk discount with zero VAT rate', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 500, discountPercent: 0, vatRate: 0 },
    ],
