  assert.equal(totals.discount, 125);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 4875);
});

test('invoiceTotals bulk discount with 9% VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 200, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 2000
  // Bulk discount (2.5%): 50
  // After discount: 1950
  // VAT: 1950 * 9% = 175.5 → 176 (banker's rounding)
  // Total: 2000 - 50 + 176 = 2126
  assert.equal(totals.subtotal, 2000);
  assert.equal(totals.discount, 50);
  assert.equal(totals.vat, 176);
  assert.equal(totals.total, 2126);
});

test('invoiceTotals complex with bulk discount and voucher', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 5, vatRate: 21 },
    ],
    voucher: { amount: 50 },
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 1000
  // First discount (5%): 50
  // After first discount: 950
  // Bulk discount (2.5% of 950): 23.75 → 24 (banker's rounding)
  // Total discount: 50 + 24 = 74
  // After discount: 926
  // VAT: 926 * 21% = 194.46 → 194
  // Voucher: 50
  // Total: 1000 - 74 + 194 - 50 = 1070
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 74);
  assert.equal(totals.voucher, 50);
});

test('invoiceTotals bulk discount multiple lines different quantities', () => {
  const invoice = {
    lines: [
      { qty: 20, unitPrice: 50, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 50, discountPercent: 0, vatRate: 21 },
      { qty: 15, unitPrice: 50, discountPercent: 0, vatRate: 21 },
