  assert.equal(totals.subtotal, 10);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 2);
  assert.equal(totals.total, 12);
});

test('invoiceTotals bulk discount large quantity', () => {
  const invoice = {
    lines: [
      { qty: 1000, unitPrice: 100, discountPercent: 0, vatRate: 21 },
