  // Total discount: 100 + 22 = 122
  // After discount: 878
  // VAT: 878 * 21% = 184.38 → 184 (banker's rounding)
  // Total: 1000 - 122 + 184 = 1062
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 122);
});

