3	/**
4	 * Calculate the total for a single line.
5	 * @param {{ qty: number, unitPrice: number }} line
6	 * @returns {number}
7	 */
8	export function lineTotal(line) {
9	  return line.qty * line.unitPrice;
10	}
11	
12	/**
13	 * Calculate subtotal, discount, VAT, voucher and total for an invoice.
14	 * VAT is calculated per line on the amount after discount, rounded per line.
15	 * Bulk discount (2.5% off) is applied to lines with 10+ units, after line discount.
16	 * Voucher is a fixed amount discount applied after VAT.
17	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { amount: number } }} invoice
18	 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
19	 */
20	export function invoiceTotals(invoice) {
21	  let subtotal = 0;
22	  let discount = 0;
23	  let vat = 0;
24	
25	  for (const line of invoice.lines) {
26	    const lineAmount = lineTotal(line);
27	    subtotal += lineAmount;
28	
29	    const lineDiscount = roundCents(lineAmount * ((line.discountPercent ?? 0) / 100));
30	    const lineAfterFirstDiscount = lineAmount - lineDiscount;
31	
32	    let bulkDiscount = 0;
33	    if (line.qty >= 10) {
34	      bulkDiscount = roundCents(lineAfterFirstDiscount * 0.025);
35	    }
36	
37	    const totalLineDiscount = lineDiscount + bulkDiscount;
38	    discount += totalLineDiscount;
39	
40	    const lineAfterAllDiscounts = lineAmount - totalLineDiscount;
41	    const lineVat = roundCents(lineAfterAllDiscounts * (line.vatRate / 100));
42	    vat += lineVat;
43	  }
44	
45	  const voucher = invoice.voucher?.amount ?? 0;
46	
47	  return {
48	    subtotal: Math.max(0, subtotal),
49	    discount: Math.max(0, discount),
50	    vat: Math.max(0, vat),
51	    voucher: Math.max(0, voucher),
52	    total: Math.max(0, subtotal - discount + vat - voucher),
53	  };
54	}
