1	import { ok, fail } from './result.js';
2	
3	export const RATES = { EUR: 1, USD: 1.085, GBP: 0.8425 };
4	
5	/**
6	 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
7	 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
8	 * @param {number} x
9	 * @returns {number}
10	 */
11	export function roundCents(x) {
12	  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
13	  const floor = Math.floor(r);
14	  const diff = r - floor;
15	  if (diff > 0.5) return floor + 1;
16	  if (diff < 0.5) return floor === 0 ? 0 : floor;
17	  return floor % 2 === 0 ? floor : floor + 1;
18	}
19	
20	/**
21	 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
22	 * @param {number} cents
23	 * @returns {string}
24	 */
25	export function formatEuros(cents) {
26	  const sign = cents < 0 ? '-' : '';
27	  const abs = Math.abs(cents);
28	  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
29	  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
30	}
31	
32	/**
33	 * Convert cents from EUR to another currency.
34	 * @param {number} cents - amount in EUR cents
35	 * @param {string} currency - target currency (EUR, USD, or GBP)
36	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
37	 */
38	export function convert(cents, currency) {
39	  if (!(currency in RATES)) {
40	    return fail('UNKNOWN_CURRENCY');
41	  }
42	
43	  const rate = RATES[currency];
44	  const eurAmount = cents / 100;
45	  const targetAmount = eurAmount * rate;
46	  const targetCents = roundCents(targetAmount * 100);
47	
48	  return ok(targetCents);
49	}
50	
51	/**
52	 * Format cents as money in a given currency: 123456 USD -> "$1,234.56", -5 GBP -> "-£0.05".
53	 * @param {number} cents - amount in cents of the target currency
54	 * @param {string} currency - currency code (EUR, USD, or GBP)
55	 * @returns {string}
56	 */
57	export function formatMoney(cents, currency) {
58	  const sign = cents < 0 ? '-' : '';
59	  const abs = Math.abs(cents);
60	  const main = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
61	  const frac = String(abs % 100).padStart(2, '0');
62	
63	  let symbol;
64	  if (currency === 'USD') {
65	    symbol = '$';
66	  } else if (currency === 'GBP') {
67	    symbol = '£';
68	  } else {
69	    symbol = '€';
70	  }
71	
72	  return `${sign}${symbol}${main}.${frac}`;
73	}
74	
75	/**
76	 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
77	 * @param {string} text
78	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
79	 */
80	export function parseEuros(text) {
81	  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
82	  if (!m) return fail('AMOUNT_INVALID');
83	  const euros = Number(m[1].replace(/,/g, ''));
84	  const cents = Number((m[2] ?? '').padEnd(2, '0'));
85	  return ok(euros * 100 + cents);
86	}
