import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays, lastDayOfMonth } from './dates.js';
import { lineTotal, invoiceTotals } from './totals.js';

function isPositiveInteger(n) {
  return Number.isInteger(n) && n > 0;
}

function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && !isNaN(discountPercent) && discountPercent >= 0 && discountPercent <= 100;
}

function calculateDueDate(issueDate, terms) {
  switch (terms) {
    case 'NET14':
      return addDays(issueDate, 14);
    case 'NET30':
      return addDays(issueDate, 30);
    case 'EOM':
      return lastDayOfMonth(issueDate);
    default:
      return null;
  }
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, terms: string, dueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  const termsToUse = terms ?? 'NET30';
  if (!['NET14', 'NET30', 'EOM'].includes(termsToUse)) {
    return fail('TERMS_INVALID');
  }

  const dueDate = calculateDueDate(issueDate, termsToUse);

  if (!lines || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    const { sku, qty, discountPercent } = line;

    if (!isPositiveInteger(qty)) return fail('QTY_INVALID');

    const discountToUse = discountPercent !== undefined ? discountPercent : TIER_DISCOUNTS[customer.tier];
    if (!isValidDiscount(discountToUse)) return fail('DISCOUNT_INVALID');

    const productResult = getProduct(sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discountToUse,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    terms: termsToUse,
    dueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

export { lineTotal, invoiceTotals } from './totals.js';

/**
 * Add a line to an invoice (or increase qty if SKU already exists).
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!isPositiveInteger(qty)) return fail('QTY_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  let discountToUse;
  if (existingLineIndex !== -1) {
    discountToUse = discountPercent !== undefined ? discountPercent : newLines[existingLineIndex].discountPercent;
  } else {
    if (discountPercent !== undefined) {
      discountToUse = discountPercent;
    } else {
      const customerResult = getCustomer(invoice.customerId);
      if (!customerResult.ok) return customerResult;
      discountToUse = TIER_DISCOUNTS[customerResult.value.tier];
    }
  }

  if (!isValidDiscount(discountToUse)) return fail('DISCOUNT_INVALID');

  if (existingLineIndex !== -1) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
      discountPercent: discountToUse,
    };
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discountToUse,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and setting status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {string[]} existingNumbers - invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: object }} invoice
 * @param {{ code: string, amount: number }} params
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  if (!isPositiveInteger(amount)) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

import { roundCents } from './money.js';

/**
 * Calculate the total for a single line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate subtotal, discount, VAT, voucher and total for an invoice.
 * VAT is calculated per line on the amount after discount, rounded per line.
 * Bulk discount (2.5% off) is applied to lines with 10+ units, after line discount.
 * Voucher is a fixed amount discount applied after VAT.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  let vat = 0;

  for (const line of invoice.lines) {
    const lineAmount = lineTotal(line);
    subtotal += lineAmount;

    const lineDiscount = roundCents(lineAmount * ((line.discountPercent ?? 0) / 100));
    const lineAfterFirstDiscount = lineAmount - lineDiscount;

    let bulkDiscount = 0;
    if (line.qty >= 10) {
      bulkDiscount = roundCents(lineAfterFirstDiscount * 0.025);
    }

    const totalLineDiscount = lineDiscount + bulkDiscount;
    discount += totalLineDiscount;

    const lineAfterAllDiscounts = lineAmount - totalLineDiscount;
    const lineVat = roundCents(lineAfterAllDiscounts * (line.vatRate / 100));
    vat += lineVat;
  }

  const voucher = invoice.voucher?.amount ?? 0;

  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    vat: Math.max(0, vat),
    voucher: Math.max(0, voucher),
    total: Math.max(0, subtotal - discount + vat - voucher),
  };
}

import { getCustomer } from './customers.js';
import { invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

function formatEuros(cents) {
  const euros = cents / 100;
  return euros.toFixed(2);
}

function escapeCSVField(value) {
  if (value === null || value === undefined) {
    return '';
  }
  const str = String(value);
  if (str.includes(',') || str.includes('"')) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

/**
 * Export invoices to CSV format.
 * @param {Array} invoices - invoices to export
 * @returns {string} - CSV string with header and one line per invoice
 */
export function exportCsv(invoices) {
  const header = 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n';

  const lines = invoices.map((invoice) => {
    const customerResult = getCustomer(invoice.customerId);
    const customerName = customerResult.ok ? customerResult.value.name : '';

    const totals = invoiceTotals(invoice);
    const due = balanceDue(invoice);

    const fields = [
      escapeCSVField(invoice.number ?? 'DRAFT'),
      escapeCSVField(customerName),
      escapeCSVField(invoice.issueDate),
      escapeCSVField(invoice.dueDate),
      escapeCSVField(invoice.status),
      formatEuros(totals.subtotal),
      formatEuros(totals.discount),
      formatEuros(totals.vat),
      formatEuros(totals.total),
      formatEuros(due),
    ];

    return fields.join(',') + '\n';
  });

  return header + lines.join('');
}

import { ok, fail } from './result.js';
import { invoiceTotals } from './invoices.js';
import { isValidDate } from './dates.js';

function isPositiveInteger(n) {
  return Number.isInteger(n) && n > 0;
}

/**
 * Record a payment on an invoice.
 * @param {{ status: string, payments?: Array<{ amount: number, date: string }> }} invoice
 * @param {{ amount: number, date: string }} params
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function recordPayment(invoice, { amount, date }) {
  if (invoice.status !== 'issued' && invoice.status !== 'partially_paid') {
    return fail('NOT_ISSUED');
  }

  if (!isPositiveInteger(amount)) {
    return fail('AMOUNT_INVALID');
  }

  if (!isValidDate(date)) {
    return fail('DATE_INVALID');
  }

  const totals = invoiceTotals(invoice);
  const currentlyPaid = (invoice.payments || []).reduce((sum, p) => sum + p.amount, 0);
  const stillOwed = totals.total - currentlyPaid;

  if (amount > stillOwed) {
    return fail('OVERPAYMENT');
  }

  const newPayments = [...(invoice.payments || []), { amount, date }];
  const newPaidAmount = currentlyPaid + amount;
  const newStatus = newPaidAmount >= totals.total ? 'paid' : 'partially_paid';

  return ok({
    ...invoice,
    payments: newPayments,
    status: newStatus,
  });
}

/**
 * Calculate the amount still owed on an invoice.
 * @param {{ payments?: Array<{ amount: number }> }} invoice
 * @returns {number}
