import { getCustomer } from './customers.js';
import { invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

function formatEuros(cents) {
  const euros = cents / 100;
  return euros.toFixed(2);
}

function escapeCSVField(value) {
  if (value === null || value === undefined) {
    return '';
  }
  const str = String(value);
  if (str.includes(',') || str.includes('"')) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

/**
 * Export invoices to CSV format.
 * @param {Array} invoices - invoices to export
 * @returns {string} - CSV string with header and one line per invoice
 */
export function exportCsv(invoices) {
  const header = 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n';

  const lines = invoices.map((invoice) => {
    const customerResult = getCustomer(invoice.customerId);
    const customerName = customerResult.ok ? customerResult.value.name : '';

    const totals = invoiceTotals(invoice);
    const due = balanceDue(invoice);

    const fields = [
      escapeCSVField(invoice.number ?? 'DRAFT'),
      escapeCSVField(customerName),
      escapeCSVField(invoice.issueDate),
      escapeCSVField(invoice.dueDate),
      escapeCSVField(invoice.status),
      formatEuros(totals.subtotal),
      formatEuros(totals.discount),
      formatEuros(totals.vat),
      formatEuros(totals.total),
      formatEuros(due),
    ];

    return fields.join(',') + '\n';
  });

  return header + lines.join('');
}

import { ok, fail } from './result.js';
import { invoiceTotals } from './invoices.js';
import { isValidDate } from './dates.js';

function isPositiveInteger(n) {
  return Number.isInteger(n) && n > 0;
}

/**
 * Record a payment on an invoice.
 * @param {{ status: string, payments?: Array<{ amount: number, date: string }> }} invoice
 * @param {{ amount: number, date: string }} params
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function recordPayment(invoice, { amount, date }) {
  if (invoice.status !== 'issued' && invoice.status !== 'partially_paid') {
    return fail('NOT_ISSUED');
  }

  if (!isPositiveInteger(amount)) {
    return fail('AMOUNT_INVALID');
  }

  if (!isValidDate(date)) {
    return fail('DATE_INVALID');
  }

  const totals = invoiceTotals(invoice);
  const currentlyPaid = (invoice.payments || []).reduce((sum, p) => sum + p.amount, 0);
  const stillOwed = totals.total - currentlyPaid;

  if (amount > stillOwed) {
    return fail('OVERPAYMENT');
  }

  const newPayments = [...(invoice.payments || []), { amount, date }];
  const newPaidAmount = currentlyPaid + amount;
  const newStatus = newPaidAmount >= totals.total ? 'paid' : 'partially_paid';

  return ok({
    ...invoice,
    payments: newPayments,
    status: newStatus,
  });
}

/**
 * Calculate the amount still owed on an invoice.
 * @param {{ payments?: Array<{ amount: number }> }} invoice
 * @returns {number}
 */
export function balanceDue(invoice) {
  const totals = invoiceTotals(invoice);
  const paidAmount = (invoice.payments || []).reduce((sum, p) => sum + p.amount, 0);
  return Math.max(0, totals.total - paidAmount);
}

/**
 * Check if text is a valid date in YYYY-MM-DD format.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  if (typeof text !== 'string') return false;

  const regex = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = regex.exec(text);
  if (!match) return false;

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  if (month < 1 || month > 12) return false;
  if (day < 1 || day > 31) return false;

  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/**
 * Add n days to a date (in UTC).
 * @param {string} dateStr - date in YYYY-MM-DD format
 * @param {number} n - number of days to add
 * @returns {string} - date in YYYY-MM-DD format
 */
export function addDays(dateStr, n) {
  if (!isValidDate(dateStr)) {
    throw new Error(`Invalid date: ${dateStr}`);
  }

  const [year, month, day] = dateStr.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  date.setUTCDate(date.getUTCDate() + n);

  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, '0');
  const d = String(date.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/**
 * Calculate the number of days between two dates (b - a, in whole days, using UTC).
 * @param {string} a - date in YYYY-MM-DD format
 * @param {string} b - date in YYYY-MM-DD format
 * @returns {number} - number of whole days between a and b
 */
export function daysBetween(a, b) {
  if (!isValidDate(a) || !isValidDate(b)) {
    throw new Error('Invalid date');
  }

  const [ya, ma, da] = a.split('-').map(Number);
  const [yb, mb, db] = b.split('-').map(Number);

  const dateA = new Date(Date.UTC(ya, ma - 1, da));
  const dateB = new Date(Date.UTC(yb, mb - 1, db));

  const diffMs = dateB.getTime() - dateA.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

/**
 * Get the last day of the month for a given date (in YYYY-MM-DD format).
 * @param {string} dateStr - date in YYYY-MM-DD format
 * @returns {string} - last day of the month in YYYY-MM-DD format
 */
export function lastDayOfMonth(dateStr) {
  if (!isValidDate(dateStr)) {
    throw new Error(`Invalid date: ${dateStr}`);
  }

  const [year, month] = dateStr.split('-').map(Number);
  let nextMonth = month + 1;
  let nextYear = year;
  if (nextMonth > 12) {
    nextMonth = 1;
    nextYear += 1;
  }
  const firstOfNext = `${nextYear}-${String(nextMonth).padStart(2, '0')}-01`;
  return addDays(firstOfNext, -1);
}

/**
 * Get the next invoice number for a given issue date.
 * Format: INV-<year>-<4-digit-counter>, counter resets each year starting at 0001.
 * @param {string[]} existingNumbers - array of invoice numbers already used
 * @param {string} issueDate - invoice issue date in YYYY-MM-DD format
 * @returns {string}
 */
export function nextInvoiceNumber(existingNumbers, issueDate) {
  const year = issueDate.substring(0, 4);
  const prefix = `INV-${year}-`;

  const currentYearNumbers = existingNumbers
    .filter((num) => num.startsWith(prefix))
    .map((num) => {
      const counter = num.substring(prefix.length);
      return parseInt(counter, 10);
    })
    .filter((n) => !isNaN(n));

  const maxCounter = currentYearNumbers.length === 0 ? 0 : Math.max(...currentYearNumbers);
  const nextCounter = maxCounter + 1;

  return `${prefix}${String(nextCounter).padStart(4, '0')}`;
}

/**
 * Get the next credit note number for a given issue date.
 * Format: CN-<year>-<4-digit-counter>, counter resets each year starting at 0001.
 * Credit notes use a separate counter from invoices.
 * @param {string[]} existingNumbers - array of numbers (invoices and credit notes) already used
 * @param {string} issueDate - credit note issue date in YYYY-MM-DD format
 * @returns {string}
 */
export function nextCreditNoteNumber(existingNumbers, issueDate) {
  const year = issueDate.substring(0, 4);
  const prefix = `CN-${year}-`;

  const currentYearNumbers = existingNumbers
    .filter((num) => num.startsWith(prefix))
    .map((num) => {
      const counter = num.substring(prefix.length);
      return parseInt(counter, 10);
    })
    .filter((n) => !isNaN(n));

  const maxCounter = currentYearNumbers.length === 0 ? 0 : Math.max(...currentYearNumbers);
  const nextCounter = maxCounter + 1;

  return `${prefix}${String(nextCounter).padStart(4, '0')}`;
}

