100	
101	  const product = productResult.value;
102	  const newLines = invoice.lines.map((line) => ({ ...line }));
103	
104	  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
105	
106	  let discountToUse;
107	  if (existingLineIndex !== -1) {
108	    discountToUse = discountPercent !== undefined ? discountPercent : newLines[existingLineIndex].discountPercent;
109	  } else {
110	    if (discountPercent !== undefined) {
111	      discountToUse = discountPercent;
112	    } else {
