118	
119	  if (!isValidDiscount(discountToUse)) return fail('DISCOUNT_INVALID');
120	
121	  if (existingLineIndex !== -1) {
122	    newLines[existingLineIndex] = {
123	      ...newLines[existingLineIndex],
124	      qty: newLines[existingLineIndex].qty + qty,
125	      discountPercent: discountToUse,
126	    };
127	  } else {
