41	      escapeCSVField(invoice.status),
42	      formatEuros(totals.subtotal),
43	      formatEuros(totals.discount),
44	      formatEuros(totals.vat),
45	      formatEuros(totals.total),
46	      formatEuros(due),
47	    ];
48	
49	    return fields.join(',') + '\n';
50	  });
51	
52	  return header + lines.join('');
53	}
