1	import { ok, fail } from './result.js';
2	import { invoiceTotals } from './invoices.js';
3	import { isValidDate } from './dates.js';
4	
5	function isPositiveInteger(n) {
6	  return Number.isInteger(n) && n > 0;
7	}
8	
9	/**
10	 * Record a payment on an invoice.
11	 * @param {{ status: string, payments?: Array<{ amount: number, date: string }> }} invoice
12	 * @param {{ amount: number, date: string }} params
13	 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
14	 */
15	export function recordPayment(invoice, { amount, date }) {
16	  if (invoice.status !== 'issued' && invoice.status !== 'partially_paid') {
17	    return fail('NOT_ISSUED');
18	  }
19	
20	  if (!isPositiveInteger(amount)) {
21	    return fail('AMOUNT_INVALID');
22	  }
23	
24	  if (!isValidDate(date)) {
25	    return fail('DATE_INVALID');
26	  }
27	
28	  const totals = invoiceTotals(invoice);
29	  const currentlyPaid = (invoice.payments || []).reduce((sum, p) => sum + p.amount, 0);
30	  const stillOwed = totals.total - currentlyPaid;
31	
32	  if (amount > stillOwed) {
33	    return fail('OVERPAYMENT');
34	  }
35	
36	  const newPayments = [...(invoice.payments || []), { amount, date }];
37	  const newPaidAmount = currentlyPaid + amount;
38	  const newStatus = newPaidAmount >= totals.total ? 'paid' : 'partially_paid';
39	
40	  return ok({
41	    ...invoice,
42	    payments: newPayments,
43	    status: newStatus,
44	  });
45	}
46	
47	/**
48	 * Calculate the amount still owed on an invoice.
49	 * @param {{ payments?: Array<{ amount: number }> }} invoice
50	 * @returns {number}
51	 */
52	export function balanceDue(invoice) {
53	  const totals = invoiceTotals(invoice);
54	  const paidAmount = (invoice.payments || []).reduce((sum, p) => sum + p.amount, 0);
55	  return Math.max(0, totals.total - paidAmount);
56	}
