1	/**
2	 * Check if text is a valid date in YYYY-MM-DD format.
3	 * @param {string} text
4	 * @returns {boolean}
5	 */
6	export function isValidDate(text) {
7	  if (typeof text !== 'string') return false;
8	
9	  const regex = /^(\d{4})-(\d{2})-(\d{2})$/;
10	  const match = regex.exec(text);
11	  if (!match) return false;
12	
13	  const year = parseInt(match[1], 10);
14	  const month = parseInt(match[2], 10);
15	  const day = parseInt(match[3], 10);
16	
17	  if (month < 1 || month > 12) return false;
18	  if (day < 1 || day > 31) return false;
19	
20	  const date = new Date(Date.UTC(year, month - 1, day));
21	  return (
22	    date.getUTCFullYear() === year &&
23	    date.getUTCMonth() === month - 1 &&
24	    date.getUTCDate() === day
25	  );
26	}
27	
28	/**
29	 * Add n days to a date (in UTC).
30	 * @param {string} dateStr - date in YYYY-MM-DD format
31	 * @param {number} n - number of days to add
32	 * @returns {string} - date in YYYY-MM-DD format
33	 */
34	export function addDays(dateStr, n) {
35	  if (!isValidDate(dateStr)) {
36	    throw new Error(`Invalid date: ${dateStr}`);
37	  }
38	
39	  const [year, month, day] = dateStr.split('-').map(Number);
40	  const date = new Date(Date.UTC(year, month - 1, day));
41	  date.setUTCDate(date.getUTCDate() + n);
42	
43	  const y = date.getUTCFullYear();
44	  const m = String(date.getUTCMonth() + 1).padStart(2, '0');
45	  const d = String(date.getUTCDate()).padStart(2, '0');
46	  return `${y}-${m}-${d}`;
47	}
48	
49	/**
50	 * Calculate the number of days between two dates (b - a, in whole days, using UTC).
51	 * @param {string} a - date in YYYY-MM-DD format
52	 * @param {string} b - date in YYYY-MM-DD format
53	 * @returns {number} - number of whole days between a and b
54	 */
55	export function daysBetween(a, b) {
56	  if (!isValidDate(a) || !isValidDate(b)) {
57	    throw new Error('Invalid date');
58	  }
59	
60	  const [ya, ma, da] = a.split('-').map(Number);
61	  const [yb, mb, db] = b.split('-').map(Number);
62	
63	  const dateA = new Date(Date.UTC(ya, ma - 1, da));
64	  const dateB = new Date(Date.UTC(yb, mb - 1, db));
65	
66	  const diffMs = dateB.getTime() - dateA.getTime();
67	  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
68	}
69	
70	/**
71	 * Get the last day of the month for a given date (in YYYY-MM-DD format).
72	 * @param {string} dateStr - date in YYYY-MM-DD format
73	 * @returns {string} - last day of the month in YYYY-MM-DD format
74	 */
75	export function lastDayOfMonth(dateStr) {
76	  if (!isValidDate(dateStr)) {
77	    throw new Error(`Invalid date: ${dateStr}`);
78	  }
79	
80	  const [year, month] = dateStr.split('-').map(Number);
81	  let nextMonth = month + 1;
82	  let nextYear = year;
83	  if (nextMonth > 12) {
84	    nextMonth = 1;
85	    nextYear += 1;
86	  }
87	  const firstOfNext = `${nextYear}-${String(nextMonth).padStart(2, '0')}-01`;
88	  return addDays(firstOfNext, -1);
89	}
