1	/**
2	 * Get the next invoice number for a given issue date.
3	 * Format: INV-<year>-<4-digit-counter>, counter resets each year starting at 0001.
4	 * @param {string[]} existingNumbers - array of invoice numbers already used
5	 * @param {string} issueDate - invoice issue date in YYYY-MM-DD format
6	 * @returns {string}
7	 */
8	export function nextInvoiceNumber(existingNumbers, issueDate) {
9	  const year = issueDate.substring(0, 4);
10	  const prefix = `INV-${year}-`;
11	
12	  const currentYearNumbers = existingNumbers
13	    .filter((num) => num.startsWith(prefix))
14	    .map((num) => {
15	      const counter = num.substring(prefix.length);
16	      return parseInt(counter, 10);
17	    })
18	    .filter((n) => !isNaN(n));
19	
20	  const maxCounter = currentYearNumbers.length === 0 ? 0 : Math.max(...currentYearNumbers);
21	  const nextCounter = maxCounter + 1;
22	
23	  return `${prefix}${String(nextCounter).padStart(4, '0')}`;
24	}
25	
26	/**
27	 * Get the next credit note number for a given issue date.
28	 * Format: CN-<year>-<4-digit-counter>, counter resets each year starting at 0001.
29	 * Credit notes use a separate counter from invoices.
30	 * @param {string[]} existingNumbers - array of numbers (invoices and credit notes) already used
31	 * @param {string} issueDate - credit note issue date in YYYY-MM-DD format
32	 * @returns {string}
33	 */
34	export function nextCreditNoteNumber(existingNumbers, issueDate) {
35	  const year = issueDate.substring(0, 4);
36	  const prefix = `CN-${year}-`;
37	
38	  const currentYearNumbers = existingNumbers
39	    .filter((num) => num.startsWith(prefix))
40	    .map((num) => {
41	      const counter = num.substring(prefix.length);
42	      return parseInt(counter, 10);
43	    })
44	    .filter((n) => !isNaN(n));
45	
46	  const maxCounter = currentYearNumbers.length === 0 ? 0 : Math.max(...currentYearNumbers);
47	  const nextCounter = maxCounter + 1;
48	
49	  return `${prefix}${String(nextCounter).padStart(4, '0')}`;
50	}
