1	import { getCustomer } from './customers.js';
2	import { formatEuros, roundCents } from './money.js';
3	import { lineTotal, invoiceTotals } from './invoices.js';
4	import { ok } from './result.js';
5	
6	/**
7	 * Render an invoice as plain text.
8	 * First line: invoice number or "DRAFT", then customer name, one line per item,
9	 * and finally a total line. All amounts formatted as euros.
10	 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }> }} invoice
11	 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
12	 */
13	export function renderInvoiceText(invoice) {
14	  const customerResult = getCustomer(invoice.customerId);
15	  if (!customerResult.ok) return customerResult;
16	
17	  const customer = customerResult.value;
18	  const { subtotal, discount, vat, voucher, total } = invoiceTotals(invoice);
19	
20	  const lines = [];
21	
22	  lines.push(invoice.number ?? 'DRAFT');
23	  lines.push(customer.name);
24	
25	  for (const line of invoice.lines) {
26	    const lineAmount = lineTotal(line);
27	    const formattedUnitPrice = formatEuros(line.unitPrice);
28	    const formattedLineTotal = formatEuros(lineAmount);
29	    lines.push(`${line.qty} x ${line.name} @ ${formattedUnitPrice} = ${formattedLineTotal}`);
30	
31	    if ((line.discountPercent ?? 0) > 0) {
32	      const lineDiscount = roundCents(lineAmount * ((line.discountPercent ?? 0) / 100));
33	      lines.push(`  ${line.discountPercent}% discount: -${formatEuros(lineDiscount)}`);
34	    }
35	  }
36	
37	  if (discount > 0 || vat > 0 || voucher > 0) {
38	    lines.push(`Subtotal: ${formatEuros(subtotal)}`);
39	    if (discount > 0) {
40	      lines.push(`Discount: -${formatEuros(discount)}`);
41	    }
42	    if (vat > 0) {
43	      lines.push(`VAT: ${formatEuros(vat)}`);
44	    }
45	    if (voucher > 0) {
46	      lines.push(`Voucher: -${formatEuros(voucher)}`);
47	    }
48	  }
49	  lines.push(`Total: ${formatEuros(total)}`);
50	
51	  return ok(lines.join('\n'));
52	}
